import{_ as n,o as s,c as t,a3 as i}from"./chunks/framework.BlfGB29P.js";const a="/images/logic-studio/user-guide/blocks-a-de.png",p=JSON.parse('{"title":"Blocks A","description":"","frontmatter":{},"headers":[],"relativePath":"projects/logic-studio/user-guide/blocks-a.md","filePath":"projects/logic-studio/user-guide/blocks-a.md","lastUpdated":1795870063000}'),r={name:"projects/logic-studio/user-guide/blocks-a.md"};function l(o,e,d,h,u,g){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="blocks-a" tabindex="-1">Blocks A <a class="header-anchor" href="#blocks-a" aria-label="Permalink to &quot;Blocks A&quot;">​</a></h1><p><strong>Arbeitsfläche ab 0.1.137:</strong> Punkteraster ohne Einrasten. Mausrad verschiebt die Ansicht; Shift + Mausrad verschiebt horizontal. Strg + Mausrad zoomt. Zoomtasten und Pinch sind ebenfalls verfügbar. Gespeicherte Blockpositionen bleiben erhalten.</p><p><strong>Hinweis zu 0.1.136:</strong> Der neue Zustandstrigger und die automatische bestätigte Schreibreihenfolge betreffen <strong>Blocks JS</strong>. Blocks-A-YAML behält die native Ereignisbrücke. Beide Sensorvarianten bleiben verfügbar; Freigaben und gespeicherte Projekte bleiben erhalten. Die Feldübernahme ohne Enter sowie „Protokoll leeren“ gehören zur gemeinsamen Studio-Oberfläche. 99 lokale Tests erfolgreich, Zusätzlich am 28.11.2026 nach Vollsicherung auf HA 2026.11.3 (.193, Port 80) live geprüft: Blocks-JS-Zustands-/Attributzweige, Schreiben vor Debug, Dezimalfeld ohne Enter, Hinweis auf alten Runtime-Code und Protokoll-Leeren. Testwerte wiederhergestellt, Projekte und Freigaben erhalten; Beispiele gestoppt. <a href="./../#zustandstrigger-reihenfolge">Live-Testnachweis</a>.</p><p><strong>0.1.135:</strong> Alle 51 direkten Entitätsfelder in 285 registrierten Blocks-A-/Blocks-JS-Bausteinen auf die HA-Auswahl geprüft. Die neue Mehrfachauswahl und die kompakteren Änderungsauslöser betreffen Blocks JS. Bestehende strukturierte HA-Zielfelder, Listen und gespeicherte Zuordnungen in Blocks A bleiben erhalten. 68 Node- und 12 Server-Tests erfolgreich; kein HA-Livetest für diese Version.</p><h2 id="sensorzustand-setzen" tabindex="-1">Sensorzustand setzen <a class="header-anchor" href="#sensorzustand-setzen" aria-label="Permalink to &quot;Sensorzustand setzen {#sensorzustand-setzen}&quot;">​</a></h2><h3 id="sensor-dezimalzahl" tabindex="-1">Dezimalzahl direkt eingeben <a class="header-anchor" href="#sensor-dezimalzahl" aria-label="Permalink to &quot;Dezimalzahl direkt eingeben {#sensor-dezimalzahl}&quot;">​</a></h3><p>Seit <strong>0.1.134</strong>: Wähle unter <strong>System → Sensorzustand setzen · Dezimalzahl</strong> einen Sensor und gib den Wert direkt ein. Vorgabe <code>0.5</code>, etwa <code>33.25</code> mit Punkt als Dezimaltrennzeichen. Es erfolgt keine Ganzzahlrundung; Speichern und Neuladen erhalten den Wert. Der bisherige Baustein mit Werteingang bleibt verfügbar. WRITE-Freigabe und Sensorattribute werden wie beim bisherigen Baustein behandelt. Blocks A benötigt die laufende Studio-App.</p><p><strong>Geprüft:</strong> 72 lokale Tests sowie nach Sicherung auf HA 2026.11.3 die Werte <code>0.5</code> und <code>33.25</code>: Blocks JS per Play, Blocks A über die generierten und geprüften Ereignisdaten. Beide Zahlenfelder nach Neuladen bestätigt, Einstellungen und Attribute erhalten.</p><p>Ab <strong>0.1.133</strong> steht unter <strong>System</strong> der Baustein <strong>Sensorzustand setzen</strong> bereit:</p><ol><li>Wähle einen vorhandenen <code>sensor.*</code> über die HA-typische Entitätenauswahl.</li><li>Verbinde den Werteingang mit einer Zahl, einem Text oder einer Berechnung (höchstens 255 Zeichen als Zustand).</li><li>Gib den Sensor in der App-Konfiguration unter <strong>WRITE – einzelne Ziele</strong> (<code>runtime_write_entities</code>) frei. Vorhandene Einträge erhalten. READ allein genügt nicht.</li><li>Wähle <strong>Blöcke prüfen → Als HA-YAML öffnen</strong>. Installiere die geprüfte Automation anschließend selbst in Home Assistant.</li></ol><p>Beispiel der erzeugten Aktion:</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">event</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">logic_studio_set_sensor_state</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    event_data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      entity_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sensor.example</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      state</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">43</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Die laufende Studio-App empfängt das Ereignis und prüft WRITE. Ohne laufende App erfolgt keine Verarbeitung. Für diesen internen Eingang ist keine allgemeine EVENT-Freigabe nötig. Fehler stehen im App-Protokoll; ein erfolgreich ausgelöstes Ereignis bestätigt noch keinen erfolgreichen Schreibzugriff.</p><p>Der Baustein erhält Einheit, Geräteklasse und andere Attribute. Er verhält sich wie <strong>Entwicklerwerkzeuge → Zustände</strong>, schaltet kein Gerät und legt keinen dauerhaften Sensor an. Die zuständige Integration kann den Wert später ersetzen. Die YAML-Vorschau führt keinen Schreibzugriff aus.</p><h2 id="erstes-beispiel" tabindex="-1">Erstes Beispiel <a class="header-anchor" href="#erstes-beispiel" aria-label="Permalink to &quot;Erstes Beispiel&quot;">​</a></h2><p>Die Beispielautomation schaltet das Flurlicht ein, sobald der Bewegungssensor <code>on</code> meldet.</p><ol><li>Wähle <strong>Neues Projekt → Blocks A</strong> und gib dem Projekt einen Namen. Auf der Fläche steht der Block <strong>Automation</strong>.</li><li>Öffne <strong>Auslöser</strong> und ziehe den Zustandsblock in <strong>Wenn</strong>. Im Bild steht <code>binary_sensor.flur_bewegung</code> mit dem Zielzustand <code>on</code>. Wähle auf deinem System deinen Testhelfer oder Sensor.</li><li>Öffne <strong>Aktionen</strong> und ziehe den Schaltblock in <strong>Dann</strong>. Im Bild steht <code>light.flur</code> auf <strong>einschalten</strong>. Für deinen ersten Versuch kannst du einen zweiten Testhelfer als Ziel verwenden. <strong>Nur wenn</strong> bleibt in diesem Beispiel leer.</li><li>Klicke auf das Fähnchen <strong>Blöcke prüfen</strong>. Wenn die Prüfung erfolgreich ist, wähle <strong>Als HA-YAML öffnen</strong>. Kontrolliere im Entwurf <code>triggers</code> und <code>actions</code>, bevor du exportierst.</li></ol><p><a href="/images/logic-studio/user-guide/blocks-a-de.png"><img src="`+a+'" alt="Blocks A mit Zustandsauslöser in Wenn und Schaltaktion in Dann"></a></p><h2 id="funktionen" tabindex="-1">Funktionen <a class="header-anchor" href="#funktionen" aria-label="Permalink to &quot;Funktionen&quot;">​</a></h2><h3 id="blockpalette-und-anschlusse" tabindex="-1">Blockpalette und Anschlüsse <a class="header-anchor" href="#blockpalette-und-anschlusse" aria-label="Permalink to &quot;Blockpalette und Anschlüsse&quot;">​</a></h3><p>Wähle einen Block aus und setze ihn an die passende Stelle. Die Form zeigt, ob er einen Wert liefert oder eine Aktion ausführt.</p><h3 id="ausloser-und-bedingungen" tabindex="-1">Auslöser und Bedingungen <a class="header-anchor" href="#ausloser-und-bedingungen" aria-label="Permalink to &quot;Auslöser und Bedingungen&quot;">​</a></h3><p>Der Auslöser startet die Automation. Eine Bedingung prüft zum Beispiel, ob der zweite Helfer bereits aus ist.</p><h3 id="aktionen-und-reihenfolge" tabindex="-1">Aktionen und Reihenfolge <a class="header-anchor" href="#aktionen-und-reihenfolge" aria-label="Permalink to &quot;Aktionen und Reihenfolge&quot;">​</a></h3><p>Stecke Aktionen untereinander. Home Assistant führt sie in der exportierten Reihenfolge aus.</p><h3 id="ha-auswahl" tabindex="-1">HA-Auswahl <a class="header-anchor" href="#ha-auswahl" aria-label="Permalink to &quot;HA-Auswahl&quot;">​</a></h3><p>Wähle eine Entität, Aktion oder ein Geräte-, Bereichs-, Label- oder Etagentarget. Im YAML erkennst du das Ziel am passenden ID-Feld.</p><h3 id="ha-yaml-entwurf" tabindex="-1">HA-YAML-Entwurf <a class="header-anchor" href="#ha-yaml-entwurf" aria-label="Permalink to &quot;HA-YAML-Entwurf&quot;">​</a></h3><p>Öffne die erzeugte Automation als YAML-Entwurf. Der Entwurf zeigt den Namen des Quellprojekts.</p><h3 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h3><p>Prüfe das YAML und übernimm es in Home Assistant. Dort kannst du einen echten Auslöser und den Automations-Trace prüfen.</p><h2 id="wenn-etwas-nicht-klappt" tabindex="-1">Wenn etwas nicht klappt <a class="header-anchor" href="#wenn-etwas-nicht-klappt" aria-label="Permalink to &quot;Wenn etwas nicht klappt&quot;">​</a></h2><p>Wenn die Zielauswahl leer ist, kontrolliere, ob es auf dem verbundenen HA-System einen passenden Eintrag gibt.</p>',33)])])}const k=n(r,[["render",l]]);export{p as __pageData,k as default};
